export function clinicalFor(v){
 const t=v.trimester||2;
 let key=v.extended?v.id:v.clinicalModule?v.id:v.type;
 if(t===1&&!v.extended&&!v.clinicalModule)key=earlyKeys[key]||key;
 const entry=clinicalCatalog[key];if(!entry)return null;
 const result={...entry,findings:entry.findings.map(f=>({...f})),refs:[...entry.refs],key,trimester:t,scope:v.scope||'해당 검사의 범위·적응증에 따라 평가'};
 result.phaseNote=t===1?'1분기: 초기 발달과 크기로 관찰이 제한됩니다. 아래는 초기 의심 단서 또는 이후 정밀검사의 감별 참고이며, 정상 초기 영상은 중기 구조 평가를 대체하지 않습니다.':t===3?'3분기: 이전에 정상이어도 후기에 나타나거나 진행하는 이상이 있습니다. 골화·태위·양수로 관찰이 제한되면 그 한계를 기록합니다.':'2분기: 각 View의 필수 구조를 확인하고 이상이 의심되면 추가 단면·정밀검사로 연결합니다.';
 if(t===1&&['genitalia','kidneysag','kidneycor','kidneys','forearm','hand','foot','tibia'].includes(v.type))result.phaseNote+=' 미세 형태 이상은 이 시기에 신뢰성 있게 배제하기 어렵습니다.';
 if(t===1&&v.type==='cervix')result.phaseNote='1분기 경부 영상은 해부학 참고입니다. 짧은 경부·조산 위험에 대한 아래 설명은 주로 적절한 중기 경질 측정에 적용하며, 초기 CL 선별용으로 사용하지 않습니다.';
 if(t===1&&['heart','lvot','rvot','vessels','threevpa','aoarch','ductarch','bicaval'].includes(v.type)){
  result.phaseNote+=' 초기 심장 선별은 situs·4CV·3VT가 중심이며, 유출로·정맥 연결은 전문 검사에서도 위양성·위음성의 한계가 있습니다.';
  result.refs.push('heart');
 }
 if(v.temporal){
  if(v.type==='heart'){
   const systole=v.id==='4ch-es';result.why+=systole?' 수축기 말에는 심실 크기·수축과 닫힌 방실판막을 비교합니다.':' 이완기에는 방실판막 개방·양측 유입과 심실 충만을 비교합니다.';
   result.cycleNote=systole?'역류는 색·스펙트럴 도플러와 cine로 확인합니다. 정지영상의 판막 위치만으로 역류를 판정하지 않습니다.':'이완기 초기와 말기는 cine의 인접 프레임으로 구분합니다. 두 개의 유입이 보여도 부분 AVSD를 배제하지 않습니다.';
  }else{
   result.why+=v.id.endsWith('-ed')?' 이완기 말에는 유출로 연결과 닫힌 반월판의 형태를 확인합니다.':' 수축기에는 반월판 개방과 전향성 유출을 확인합니다.';
   result.cycleNote=v.id.endsWith('-ed')?'이완기의 반월판 닫힘·전향성 유출 부재는 정상일 수 있습니다. 협착·폐쇄는 수축기 cine와 도플러에서 평가합니다.':'유출속도와 역류·협착은 정확한 도플러 표본 위치·입사각에서 평가합니다.';
  }
 }
 if(v.direction&&v.direction!=='standard')result.directionNote='추가 방향은 같은 장기의 의심 소견을 다른 면에서 확인하는 보조 접근입니다. 아래 이상이 이 방향 한 장에서 모두 보인다는 뜻은 아니며 원래 기준 단면과 함께 평가합니다.';
 if(t===1)result.refs.push('early');else if(t===3)result.refs.push('late');
 result.sources=[...new Set(result.refs)].map(k=>clinicalSources[k]);
 return result;
}
export function renderClinical(v){
 const c=clinicalFor(v);if(!c)return '';
 return `<section class="clinical-guide" aria-label="촬영 목적과 주요 이상 소견"><div class="clinical-heading"><span class="scope">${esc(c.scope)}</span><h3>이 View를 촬영하는 이유</h3><p class="clinical-purpose">${esc(c.why)}</p></div><p class="clinical-phase">${esc(c.phaseNote)}</p>${c.cycleNote?`<p class="clinical-phase"><b>심장 주기별 해석</b> ${esc(c.cycleNote)}</p>`:''}${c.directionNote?`<p class="clinical-phase">${esc(c.directionNote)}</p>`:''}<h3>주요 이상 소견 · Anomalies & findings</h3><p class="clinical-intro">이 단면에서 찾는 단서와 감별 대상입니다. 성장·혈류·모체 소견도 포함하며, 모든 항목이 태아 구조 기형을 뜻하지는 않습니다.</p><div class="clinical-findings">${c.findings.map(f=>`<article class="clinical-finding"><h4>${esc(f.name)}</h4><dl><dt>관찰 단서</dt><dd>${esc(f.sign)}</dd><dt>추가 확인</dt><dd>${esc(f.next)}</dd></dl></article>`).join('')}</div><div class="clinical-limit"><b>이 View의 해석 한계</b><p>${esc(c.limit)}</p><p>미관찰이 곧 결손은 아닙니다. 영상 품질·주수·태위를 확인하고 여러 단면을 종합합니다. 현재 표시되는 참고 사진은 위 이상 소견의 증례 모음이 아닙니다.</p></div><details class="clinical-evidence"><summary>학회·논문 근거 ${c.sources.length}건</summary><ul>${c.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a></li>`).join('')}</ul><p>원문의 검사 목적·질환별 소견을 View별로 재구성한 교육용 요약입니다. 학회가 제시한 단면별 확진 목록이나 발생 빈도 순위가 아닙니다. 근거 확인: 2026-10-24.</p></details></section>`;
}
